"""Five-arm frozen-suite report; aggregate actual accepted GPU receipts only."""
import csv,hashlib,importlib.util,json,math
from pathlib import Path
ROOT=Path('/raid/yoon/nemochat');OUT=ROOT/'results/midtraining/sft1248-benchmark-gpu-01';HERE=ROOT/'midtraining/sft_after_kd/benchmark1248';OLD=ROOT/'midtraining/offline2b/ablation_gpu'
s=importlib.util.spec_from_file_location('accepted_controller',OLD/'controller.py');c=importlib.util.module_from_spec(s);s.loader.exec_module(c)
ORDER=['A','C','B','D','E'];LABELS={'A':'A: BASE19074','C':'C: LM+KD1000','B':'B: LM-only1000','D':'D: SFT905','E':'E: FINAL SFT1248'}
COLORS=['#4477aa','#ee7733','#228833','#aa3377','#111111']
def save(name,value):(OUT/name).write_text(json.dumps(value,indent=2,ensure_ascii=False,allow_nan=False)+'\n')
def main():
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 from PIL import Image
 suite=c.load_suite();paths={a:c.OUT/(a+'-full01/report.json') for a in ['A','C','B']};paths['D']=ROOT/'results/midtraining/sft905-benchmark-gpu-01/D-full01/report.json';paths['E']=OUT/'E-full01/report.json';reports={a:c.read(p) for a,p in paths.items()}
 models={**c.MODELS,'D':ROOT/'checkpoints/exports/nemochat_sft905_hf_bf16_01','E':ROOT/'checkpoints/exports/nemochat_sft1248_hf_bf16_01'}
 coverage={a:c.validate_report(reports[a],suite,models[a]) for a in ORDER}
 accepted=c.read(OUT/'evaluation-accepted.json');export=c.read(OUT/'export_result.json');load=c.read(OUT/'load-receipt.json');compat=c.read(OUT/'tokenizer-compatibility03.json')
 assert export['source_step']==load['source_step']==accepted['source_step']==1248
 assert compat['encoded_choices_checked']==1600 and compat['allowed_and_actual_changed_ids']==list(range(18,30))
 for phase in ['export','eval03']:
  engine=c.read(OUT/(phase+'-engine.final.json'));c.clean_engine(engine,engine['Id'])
 assert accepted['baseline_reports_unchanged'] and not accepted['baseline_reruns']
 for name in ['source-freeze.json','source-freeze02.json','source-freeze03.json']:
  for p,h in c.read(OUT/name).items():assert hashlib.sha256(Path(p).read_bytes()).hexdigest()==h
 qdir=OUT/'E-full01'
 for q in reports['E']['questions']:assert c.read(qdir/(q['id'].replace('/','__')+'.json'))==q
 hdir=OUT/'heldout-receipts';hdir.mkdir(exist_ok=False)
 for i,w in enumerate(reports['E']['heldout']):
  p=hdir/f'{i:02d}.json';p.write_text(json.dumps(w,indent=2));assert c.read(p)==w
 assert len(list(qdir.glob('*.json')))==401 and len(list(hdir.glob('*.json')))==64
 groups=[('MMLU diagnostic\n200 questions, 5-shot',lambda q:q['task'].startswith('mmlu_'),'acc'),('ARC-Challenge\n100 questions, 0-shot',lambda q:q['task']=='arc_challenge','acc_norm'),('HellaSwag\n100 questions, 0-shot',lambda q:q['task']=='hellaswag','acc_norm')]
 scores={a:[sum(q[m] for q in r['questions'] if pred(q))/sum(pred(q) for q in r['questions']) for _,pred,m in groups] for a,r in reports.items()}
 counts={a:[{'correct':sum(q[m] for q in r['questions'] if pred(q)),'n':sum(pred(q) for q in r['questions'])} for _,pred,m in groups] for a,r in reports.items()}
 sources=sorted({h['source'] for h in suite['heldout']});held={a:{'Overall':r['heldout_full_vocab_nll'],**{src:sum(w['nll_sum'] for w in r['heldout'] if w['source']==src)/sum(w['target_count'] for w in r['heldout'] if w['source']==src) for src in sources}} for a,r in reports.items()}
 ppl={a:{src:math.exp(v) for src,v in row.items()} for a,row in held.items()}
 deltas={base:{'accuracy_percentage_points':[100*(e-b) for e,b in zip(scores['E'],scores[base])],'heldout_nll':held['E']['Overall']-held[base]['Overall'],'heldout_ppl':ppl['E']['Overall']-ppl[base]['Overall']} for base in ORDER[:-1]}
 paired={};paired_rows=[]
 for base in ['D','C']:
  paired[base]={}
  for (label,pred,m),key in zip(groups,['mmlu_acc','arc_acc_norm','hellaswag_acc_norm']):
   pairs=[(d,e) for d,e in zip(reports[base]['questions'],reports['E']['questions']) if pred(e)];assert all(d['id']==e['id'] for d,e in pairs)
   paired[base][key]={'n':len(pairs),'wrong_to_correct':sum(not d[m] and bool(e[m]) for d,e in pairs),'correct_to_wrong':sum(bool(d[m]) and not e[m] for d,e in pairs),'both_correct':sum(bool(d[m]) and bool(e[m]) for d,e in pairs),'both_wrong':sum(not d[m] and not e[m] for d,e in pairs),'prediction_changed':sum(d['prediction' if m=='acc' else 'prediction_char_norm']!=e['prediction' if m=='acc' else 'prediction_char_norm'] for d,e in pairs)}
   for d,e in pairs:paired_rows.append({'baseline':base,'id':e['id'],'task':e['task'],'metric':m,'baseline_correct':d[m],'E_correct':e[m],'correct_delta':e[m]-d[m],'baseline_prediction':d['prediction' if m=='acc' else 'prediction_char_norm'],'E_prediction':e['prediction' if m=='acc' else 'prediction_char_norm']})
 with (OUT/'paired-question-deltas.csv').open('w') as f:
  w=csv.DictWriter(f,fieldnames=list(paired_rows[0]));w.writeheader();w.writerows(paired_rows)
 save('paired-question-deltas.json',{'E_minus_baseline':paired,'significance':'not_tested; descriptive paired counts only'})
 fig,ax=plt.subplots(figsize=(15,8))
 for i,a in enumerate(ORDER):
  bars=ax.bar([j+(i-2)*.165 for j in range(3)],[100*v for v in scores[a]],width=.157,color=COLORS[i],label=LABELS[a]);ax.bar_label(bars,fmt='%.1f%%',padding=4,fontsize=10)
 ax.set_xticks(range(3),[g[0] for g in groups],fontsize=12);ax.set_ylim(0,70);ax.set_ylabel('Accuracy (%) | MMLU: acc; ARC / HellaSwag: acc_norm');ax.set_title('NemoChat five-arm frozen raw-prompt GPU benchmark\nE = actual FINAL SFT1248; A/C/B/D = unchanged accepted reports',fontsize=15,pad=16);ax.legend(ncol=3,loc='upper left',fontsize=11);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
 fig.text(.06,.055,'E vs SFT905 (MMLU / ARC / HellaSwag): '+', '.join(f'{x:+.2f} pp' for x in deltas['D']['accuracy_percentage_points'])+'\n400 fixed questions / 1,600 choices; diagnostic subsets, NOT full benchmarks or leaderboard scores.\nNo chat template. E resumes D for 343 additional SFT updates; this is not a controlled KD ablation.',fontsize=11)
 fig.subplots_adjust(bottom=.25,top=.85);benchmark=OUT/'benchmark-five-arms-SFT1248.png';fig.savefig(benchmark,dpi=160);plt.close(fig)
 fig,axes=plt.subplots(2,1,figsize=(18,11));names=['Overall',*sources]
 for i,a in enumerate(ORDER):
  for ax,ys in zip(axes,[[held[a][n] for n in names],[ppl[a][n] for n in names]]):
   bars=ax.bar([j+(i-2)*.165 for j in range(len(names))],ys,width=.157,label=LABELS[a],color=COLORS[i]);ax.bar_label(bars,fmt='%.3f',padding=4,fontsize=8)
 for ax,ylabel in zip(axes,['Full-vocabulary token NLL (lower is better)','PPL = exp(NLL) (lower is better)']):
  labels=['Overall\n65,536 targets',*[n.replace('_','\n')+'\n16,384 targets' for n in sources]]
  ax.set_xticks(range(len(names)),labels,fontsize=10);ax.set_ylabel(ylabel);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True);ax.margins(y=.25)
 axes[0].legend(ncol=5,loc='upper left',fontsize=10);fig.suptitle('NemoChat five-arm pretraining-heldout retention diagnostic\nSame 64 windows x 1,024 targets; NOT SFT validation Loss',fontsize=16)
 fig.text(.055,.015,'E vs D: NLL '+f"{deltas['D']['heldout_nll']:+.9f}"+' | PPL '+f"{deltas['D']['heldout_ppl']:+.9f}"+'\nOnly E newly scored. Native/HF logit parity unrun; model byte-integrity audits explicitly waived.',fontsize=11)
 fig.tight_layout(rect=(0,.07,1,.93));hold=OUT/'heldout-five-arms-SFT1248.png';fig.savefig(hold,dpi=160);plt.close(fig)
 for p in [benchmark,hold]:
  with Image.open(p) as im:im.verify()
 summary={'status':'verified_five_arm_same_frozen_raw_prompt_GPU_comparison','order':ORDER,'labels':LABELS,'suite_sha256':suite['suite_sha256'],'source_step':1248,'source':accepted['source'],'resume_source_step':905,'segment_updates':343,'reports':{a:str(p) for a,p in paths.items()},'coverage':coverage,'benchmark_metrics_order':['mmlu_acc','arc_acc_norm','hellaswag_acc_norm'],'benchmark_accuracy':scores,'benchmark_correct_counts':counts,'heldout_nll':held,'heldout_ppl':ppl,'E_minus_baselines':deltas,'paired_E_minus_baselines':paired,'per_subject_metrics':{a:r['metrics'] for a,r in reports.items()},'export_engine_id':accepted['export_engine_id'],'E_engine_id':accepted['engine_id'],'E_engine_state':accepted['state'],'E_scoring_elapsed_seconds':reports['E']['elapsed_seconds'],'images':[str(benchmark),str(hold)],'baseline_reruns':False,'baseline_reports_unchanged':True,'source_payload_integrity':'not_checked_explicit_user_waiver','native_HF_logit_parity':'not_run','official_harness_backend':False,'official_task_source_derived_evaluator':True,'chat_template_applied':False,'individual_question_receipts':400,'individual_heldout_receipts':64,'comparison':'E is further SFT after D and C, not a controlled KD ablation','attempts_before_success':[{'phase':'eval','status':'failed_before_model_load','cause':'comparison-only BASE export tokenizer invalid UTF-8'},{'phase':'eval02','status':'failed_before_model_load','cause':'root-owned CPU preflight receipt not writable by GPU user'}],'recovery':'original local BASE tokenizer for comparison guard only; canonical vocab must match frozen suite; actual SFT1248 model/tokenizer unchanged; separate GPU receipt'}
 save('summary.json',summary)
 with (OUT/'scores.csv').open('w') as f:
  w=csv.writer(f);w.writerow(['arm','label','mmlu_acc','arc_acc_norm','hellaswag_acc_norm','heldout_nll','heldout_ppl'])
  for a in ORDER:w.writerow([a,LABELS[a],*scores[a],held[a]['Overall'],ppl[a]['Overall']])
 table='| Arm | MMLU acc /200 | ARC acc_norm /100 | HellaSwag acc_norm /100 | Heldout NLL /65,536 targets | PPL |\n|---|---:|---:|---:|---:|---:|\n'
 for a in ORDER:table+='| '+LABELS[a]+' | '+' | '.join(f'{100*v:.2f}%' for v in scores[a])+f" | {held[a]['Overall']:.15f} | {ppl[a]['Overall']:.15f} |\n"
 delta='MMLU / ARC / HellaSwag: '+', '.join(f'{v:+.2f} pp' for v in deltas['D']['accuracy_percentage_points'])+f"; Heldout NLL {deltas['D']['heldout_nll']:+.15f}; PPL {deltas['D']['heldout_ppl']:+.15f}."
 paired_text=json.dumps(paired['D'],indent=2)
 common='\n## Exact artifacts\n- `summary.json`, `scores.csv`: all five arms and exact numeric aggregation\n- `E-full01/report.json`: full E report, 400 question rows and 64 heldout windows\n- `E-full01/*.json`: all 400 individual question receipts, re-read and validated\n- `heldout-receipts/`: 64 individual heldout receipts\n- `paired-question-deltas.{json,csv}`: descriptive D/E and C/E paired counts\n- `export_result.json`, `mapping_provenance.json`, `excluded_native_records.json`, `load-receipt.json`: native-to-HF/full-load provenance\n- `tokenizer-compatibility03.json`: 1,600 frozen encodings and reserved-alias identity proof\n- `export-engine.*`, `eval03-engine.*`: exact Engine IDs, specs, logs and clean final states\n- Initial failed attempts and source freezes are preserved; see `recovery-disclosure.json` and `recovery03-disclosure.json`.\n\n![Benchmark](benchmark-five-arms-SFT1248.png)\n\n![Heldout](heldout-five-arms-SFT1248.png)\n'
 en='# FINAL SFT1248: five-arm frozen GPU benchmark\n\n'+table+'\n## E1248 versus D905\n'+delta+'\n\nPaired question outcomes (descriptive, no statistical-significance claim):\n```json\n'+paired_text+'\n```\n\nOnly E was scored in this task. Existing BASE A, LM+KD C, LM-only B and SFT905 D reports were validated and reused unchanged. The actual FINAL `iter_0001248` native checkpoint was exported, not substituted with SFT905 or C. E is 343 full-state-resumed updates after D905; SFT is initialized from C, so the five-arm comparison is not a controlled KD ablation.\n\nProtocol: same canonical suite SHA `'+suite['suite_sha256']+'`; MMLU 10 subjects x20 test questions at 5-shot, ARC-Challenge100 test and HellaSwag100 validation at 0-shot. 400 questions /1,600 choices; 64 heldout windows /65,536 targets. Not full benchmark/leaderboard results. Training contamination is unproven. Heldout NLL/PPL measures pretraining retention, not SFT validation Loss.\n\nThe original GPU scorer is unchanged: official-task-source-derived evaluation, not direct official harness execution. Raw prompts, no chat template, full-vocabulary likelihood, MMLU acc and character-normalized ARC/HellaSwag acc_norm. All frozen question IDs/order/golds, metrics and per-question receipts validated through the old controller.\n\nRuntime: official Transformers5.12.1 / Torch2.13.0a0+8145d630e8.nv26.06, one B300 GPU, eager BF16, TF32 false, no padding, unchanged parameters and finite loaded/forward tensors. Native619 records map exhaustively to447 runtime /6,289 serialized records; 9,790,967,416 parameters,52 layers,23 FP32 router buffers and time_step_min0 are preserved. No missing/unexpected/mismatched keys. Export and successful evaluation Engines exited0, OOMKilled=false. Scoring elapsed '+f"{reports['E']['elapsed_seconds']:.6f}"+' seconds. Source payload byte integrity: not_checked_explicit_user_waiver. Native/HF logit parity: not_run.\n\nRecovery disclosure: the first evaluation failed before loading any model because the comparison-only BASE export tokenizer was invalid UTF-8. A no-device preflight reproduced it and verified the original local BASE tokenizer against the immutable suite vocabulary. Only that comparison guard uses the equivalent original tokenizer; evaluated E retains the exact migrated SFT tokenizer from accepted SFT905 assets. Differences are confined to reserved IDs18..29, all1,600 frozen encodings match, and heldout windows contain none of those IDs. The second attempt failed before model load because the CPU preflight receipt was root-owned; a new GPU-owned receipt path resolved the conflict. Prior evidence is preserved; successful E scoring ran once. No training, downloads, Hub writes, baseline reruns, source-weight audits or subset changes.\n'+common
 ko='# FINAL SFT1248: 동일 frozen GPU benchmark 5-arm 비교\n\n'+table+'\n## E1248 vs D905\n'+delta+'\n\nD/E paired 문항 결과(기술 통계이며 통계적 유의성은 검정하지 않음):\n```json\n'+paired_text+'\n```\n\n이번 작업에서 E만 새로 scoring했습니다. BASE A / LM+KD C / LM-only B / SFT905 D는 기존 report를 재검증하여 변경 없이 사용했습니다. 실제 FINAL native `iter_0001248`에서 export했으며 SFT905나 C의 weight로 대체하지 않았습니다. E는 D905에서 optimizer/RNG/cursor를 이어받아 343 update를 더 수행한 결과입니다. C 이후 추가 SFT가 있으므로 통제된 KD ablation은 아닙니다.\n\n동일 canonical suite SHA `'+suite['suite_sha256']+'`를 사용했습니다. MMLU는 10 subject x20 test question의 5-shot, ARC-Challenge100 test / HellaSwag100 validation은 0-shot입니다. 400 question /1,600 choice, heldout64 window /65,536 target 전부를 기존 controller로 검증했습니다. 전체 benchmark나 leaderboard 점수는 아니며 contamination 여부는 확인되지 않았습니다. Heldout NLL/PPL은 pretraining retention diagnostic이지 SFT validation Loss가 아닙니다.\n\n기존 GPU scorer의 scoring/aggregation은 변경하지 않았습니다. Official-task-source-derived evaluator이며 official harness 직접 실행은 아닙니다. 동일 RAW prompt, chat template 미적용, full-vocabulary likelihood, MMLU acc / ARC와 HellaSwag acc_norm입니다.\n\nOfficial Transformers5.12.1 / Torch2.13, B300 GPU1개, eager BF16, TF32=false, no-padding, parameter unchanged를 검증했습니다. Native619 ->runtime447 /serialized6,289 record, 9,790,967,416 parameter,52 layer,23 FP32 router buffer,time_step_min0을 보존했습니다. 모든 loaded tensor가 finite이며 missing/unexpected/mismatched key가 없습니다. Export와 최종 evaluation Engine은 exit0/OOMKilled=false입니다. E scoring 시간은 '+f"{reports['E']['elapsed_seconds']:.6f}"+'초입니다. Source payload byte integrity는 사용자 waiver로 미검사, native/HF logit parity는 미실행입니다.\n\n복구 이력: 첫 시도는 비교용 BASE export tokenizer의 UTF-8 오류로 model load 전에 중단됐습니다. CPU preflight에서 재현했고 로컬 원본 BASE tokenizer의 canonical vocabulary가 frozen suite와 정확히 같음을 확인하여 비교 guard에만 사용했습니다. 실제 평가 모델/tokenizer는 FINAL SFT1248과 SFT905에서 그대로 복사한 migrated asset을 유지했습니다. 변경 alias는 ID18..29뿐이고 전체1,600 encoding이 동일하며 heldout에는 해당 ID가 없습니다. 두 번째는 CPU preflight receipt의 root 소유권 때문에 model load 전에 실패하여 GPU 전용 새 receipt 경로로 분리했습니다. 실패 근거는 보존했고 실제 전체 E scoring은 한 번 실행했습니다. 학습/다운로드/Hub write/기존 arm 재실행/source weight audit/subset 변경은 없었습니다.\n'+common
 (OUT/'FINAL_REPORT.md').write_text(en);(OUT/'FINAL_REPORT.ko.md').write_text(ko);print(table);print(delta);print('IMAGES',summary['images'])
if __name__=='__main__':main()
